public static int findNthLeapYear(int Y, int N) {
    // Define a helper method to check if a year is a leap year
    int count = 0;
    int year = Y + 1; // Start checking from the next year after Y

    while (count < N) {
        if (isLeapYear(year)) {
            count++;
        }
        if (count < N) {
            year++;
        } else {
            return year;
        }
    }
    return year;
}

