public static String appx(String word1, String word2) {
    // Convert to uppercase for case-insensitive comparison
    char[] chars1 = word1.toUpperCase().toCharArray();
    char[] chars2 = word2.toUpperCase().toCharArray();

    // Count frequency of each character in word1
    int[] freq1 = new int[26];
    for (char c : chars1) {
        if (c >= 'A' && c <= 'Z') {
            freq1[c - 'A']++;
        }
    }

    // Count common letters
    int common = 0;
    for (char c : chars2) {
        if (c >= 'A' && c <= 'Z') {
            int idx = c - 'A';
            if (freq1[idx] > 0) {
                freq1[idx]--;
                common++;
            }
        }
    }

    // Calculate the denominator (sum of lengths)
    int len1 = word1.length();
    int len2 = word2.length();
    int denominator = len1 + len2;
    int numerator = common;

    // Reduce the fraction
    if (numerator == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = gcd(numerator, denominator);
    if (gcd != 0) {
        numerator /= gcd;
        denominator /= gcd;
    }

    // If the fraction reduces to 1 (numerator == denominator), just return "1"
    if (numerator == denominator) {
        return "appx(" + word1 + ", " + word2 + ") = 1";
    }

    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

