public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    int[] freq = new int[26];
    char[] chars = s.toCharArray();
    for (char c : chars) {
        freq[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    int totalChars = s.length();
    int picked = 0;

    while (picked < totalChars) {
        // Step 1-3: Pick smallest, then increasing
        for (int i = 0; i < 26 && picked < totalChars; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                picked++;
            }
        }

        // Step 4-6: Pick largest, then decreasing
        for (int i = 25; i >= 0 && picked < totalChars; i--) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                picked++;
            }
        }
    }

    return result.toString();
}

