public boolean hasAllCodes(String s, int k) {
    if (k > s.length()) {
        return false;
    }

    // Total number of unique binary strings of length k
    int totalUnique = 1 << k;

    // Set to store the binary representation of substrings
    Set<Integer> seen = new HashSet<>();

    // Sliding window approach
    int n = s.length();
    int windowValue = 0;

    // Initialize the first window
    for (int i = 0; i < k; i++) {
        windowValue = (windowValue << 1) | (s.charAt(i) - '0');
    }
    seen.add(windowValue);

    // Slide the window
    for (int i = k; i < n; i++) {
        // Remove the leftmost bit (mask to k bits)
        windowValue = ((windowValue << 1) & ((1 << k) - 1)) | (s.charAt(i) - '0');
        seen.add(windowValue);

        // Early termination if we've seen all unique binary strings
        if (seen.size() == totalUnique) {
            return true;
        }
    }

    return seen.size() == totalUnique;
}

