    // = 2 * [15 - 3] + (-5)*3
    // = 2*12 - 15 = 24-15=9. Correct.

    long target = n;
    long m = (long) (n - 1) / 2 + 1;
    // To avoid overflow for large n, we can use the formula:
    long total = 2 * ( ( (long)(n-1) * n ) / 2 - ( (long)(m-1) * m ) / 2 ) + (long)(1 - n) * (n - m);
    return (int) total;
