        for (int i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                count++;
                if (count == k) {
                    return i;
                }
                int other = n / i;
                if (other != i) {
                    count++;
                    if (count == k) {
                        return other;
                    }
                }
            }
        }

        // We need to collect all factors and find the k-th one
        // Actually, the above approach doesn't work for larger k, so let's use a different approach
        // Let's collect all small factors and large factors
        int[] smallFactors = new int[100000]; // More than enough for n <= 10000
        int[] largeFactors = new int[100000];
        int smallCount = 0;
        int largeCount = 0;

        for (int i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                smallFactors[smallCount++] = i;
                if (i != n / i) {
                    largeFactors[largeCount++] = n / i;
                }
            }
        }

        int totalFactors = smallCount + largeCount;
        if (k > totalFactors) {
            return -1;
        }

        // The factors in ascending order are: smallFactors in ascending order, then largeFactors in descending order
        if (k <= smallCount) {
            return smallFactors[k - 1];
        } else {
            int indexInLarge = k - smallCount - 1;
            // largeFactors are stored in ascending order (as i goes from small to large, n/i goes from large to small)
            // So we need to access in reverse
            return largeFactors[largeCount - 1 - indexInLarge];
        }
    }

