public String makeGood(String s) {
    // Use a stack to simulate the process
    // When we find adjacent characters that form a "bad" pair,
    // we can think of it as "canceling" them out

    // Key insight: if we process the string left to right and maintain a stack,
    // when the current character and the top of the stack form a "bad" pair,
    // we can pop the stack instead of adding the current character
    // This simulates removing the adjacent pair

    char[] stack = new char[s.length()];
    int top = 0; // points to the next position to write

    for (char c : s.toCharArray()) {
        // Check if current char and top of stack form a "bad" pair
        // A "bad" pair is when one is lowercase and the other is uppercase
        // and they represent the same letter

        if (top > 0) {
            char prev = stack[top - 1];
            // Check if they are the same letter but different case
            // Math.abs('a' - 'A') = 32, so if absolute difference is 32 and same letter
            if (Math.abs(c - prev) == 32) {
                // They form a "bad" pair, so we "cancel" them
                // Instead of adding c, we just pop the previous character
                top--;
            } else {
                // Not a bad pair, so add current character to stack
                stack[top++] = c;
            }
        } else {
            // Stack is empty, just add current character
            stack[top++] = c;
        }
    }

    // Build the result string from the stack
    return new String(stack, 0, top);
}

