        int lastDigit = num % 10;
        if (lastDigit > 0) {
            int newNum = num * 10 + (lastDigit - 1);
            if (newNum <= high) {
                queue.offer(newNum);
            }
        }
        if (lastDigit < 9) {
            int newNum = num * 10 + (lastDigit + 1);
            if (newNum <= high) {
                queue.offer(newNum);
            }
        }
    }

    if (low == 0) {
        result.add(0);
        Collections.sort(result);
    }

    return result;
}

