            return 0;
        }
        int endNumber = 450;
        int[] squares = new int[endNumber];
        for (int i = 0; i <= endNumber; i++) {
            squares[i] = (int) Math.sqrt(i);
        }

        int n = A.length;
        int[] count = new int[endNumber + 1];
        for (int num : A) {
            count[num]++;
        }

        // Precompute if sum of two numbers is a perfect square
        int nCount = count.length;
        int countSum = 0;
        for (int c : count) {
            countSum += c;
        }

        // We need to count distinct permutations (considering duplicates)
        // Using backtracking with dictionary (count array) to avoid duplicates
        int[] perm = new int[n];
        int countArray = nCount;
        boolean[] isSquare = new boolean[endNumber * 2 + 1];
        for (int i = 0; i < isSquare.length; i++) {
            isSquare[i] = (i == 0) || (i > 0); // 0 is a perfect square
        }
        // Actually, let me redo the perfect square check
        // The max sum of two numbers is 2 * 449
        int maxSum = endNumber * 2;
        for (int i = 0; i <= maxSum; i++) {
            int sqrtI = (int) Math.sqrt(i);
            isSquare[i] = (sqrtI * sqrtI == i);
        }

        // Backtracking function
        // We use count array to track remaining elements
        return backtrack(0, n, A, count, perm, isSquare);
    }

