public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    if (n == 0) {
        return 0;
    }

    int[] leftSmaller = new int[n];
    int[] rightSmaller = new int[n];
    int[] stack = new int[n];
    int top = -1;

    // Find the index of the previous bar with smaller height for each bar
    for (int i = 0; i < n; i++) {
        while (top >= 0 && heights[i] <= heights[stack[top]]) {
            top--;
        }
        leftSmaller[i] = (top >= 0) ? stack[top] + 1 : 0;
        stack[++top] = i;
    }

    // Reset stack
    top = -1;

    // Find the index of the next bar with smaller height for each bar
    for (int i = n - 1; i >= 0; i--) {
        while (top >= 0 && heights[i] <= heights[stack[top]]) {
            top--;
        }
        rightSmaller[i] = (top >= 0) ? stack[top] - 1 : n - 1;
        stack[++top] = i;
    }

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        int width = rightSmaller[i] - leftSmaller[i] + 1;
        int area = heights[i] * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }

    return maxArea;
}

