public static int findSmallestInteger(int n) {
        char[] digits = Integer.toString(n).toCharArray();
        int len = digits.length;

        // Step 1: Find the rightmost digit that is smaller than the digit after it
        int i = len - 2;
        while (i >= 0 && digits[i] >= digits[i + 1]) {
            i--;
        }

        // If no such digit is found, the number is the largest possible (descending order)
        if (i < 0) {
            return -1;
        }

        // Step 2: Find the smallest digit on the right side of i that is still greater than digits[i]
        int j = len - 1;
        while (j > i && digits[j] <= digits[i]) {
            j--;
        }

        // Step 3: Swap the found digits
        char temp = digits[i];
        digits[i] = digits[j];
        digits[j] = temp;

        // Step 4: Reverse the suffix starting at i+1
        // We use a helper method to reverse a subarray
        int left = i + 1, right = len - 1;
        while (left < right) {
            char t = digits[left];
            digits[left] = digits[right];
            digits[right] = t;
            left++;
            right--;
        }

        // Convert back to int
        return Integer.parseInt(new String(digits));
    }

