    // A boomerang consists of 3 distinct points that are not collinear.
    // To check if three points are collinear, we can use the cross product (determinant method).
    // Let A = points[0], B = points[1], C = points[2]
    // If (B - A) x (C - A) == 0, then the points are collinear.
    // The cross product in 2D is: (Bx - Ax) * (Cy - Ay) - (By - Ay) * (Cx - Ax)
    // If this value is not zero, the points are not collinear, hence form a boomerang.
    // Also, all three points must be distinct.

    int ax = points[0][0], ay = points[0][1];
    int bx = points[1][0], by = points[1][1];
    int cx = points[2][0], cy = points[2][1];

    // Check if any two points are identical
    if (ax == bx && ay == by) return false;
    if (ax == cx && ay == cy) return false;
    if (bx == cx && by == cy) return false;

    // Calculate cross product
    int cross = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);

    // If cross product is non-zero, the points are not collinear
    return cross != 0;
}

