public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    // Base case: n itself is a perfect square
    int root = (int) Math.sqrt(n);
    if (root * root == n) {
        return 1;
    }

    // Check if n can be represented as sum of 2 perfect squares
    for (int i = 1; i * i <= n; i++) {
        int remaining = n - i * i;
        int j = (int) Math.sqrt(remaining);
        if (j * j == remaining) {
            return 2;
        }
    }

    // Check if n can be represented as sum of 3 perfect squares
    // According to Legendre's Three-Square Theorem, a natural number can be represented as
    // the sum of three integer squares if and only if n is not of the form 4^a(8b+7)
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 != 7) {
        return 3;
    }

    return 4;
}

